class V:
    def __init__(self, x):
        self.x = x
    def __add__(self, other):
        return V(self.x + other.x)

s = V(2) + V(3)
print(s.x)

class Square:
    def __init__(self, s):
        side = s
    def area(self):
        return self.side * self.side
sq = Square(4)
print(sq.area())

class Animal:
    def __init__(self, name):
        self.name = name
        self.sound = "silent"
class Dog(Animal):
    def __init__(self, name):
        self.sound = "woof"
        super().__init__(name)
d = Dog("Rex")
print(d.name, d.sound)

class Account:
    def __init__(self, bal):
        self.bal = bal
    def withdraw(self, amt):
        self.bal -= amt
class Savings(Account):
    def withdraw(self, amt):
        Account.withdraw(self, amt + 10)
s = Savings(100)
s.withdraw(20)
print(s.bal)

class Thermostat:
    def __init__(self):
        self.__temp = 20
    def set_temp(self, t):
        if 10 <= t <= 30:
            self.__temp = t
        return self.__temp
th = Thermostat()
th.set_temp(25)
print(th.set_temp(45))

class Report:
    def __fmt(self, x):
        return "[" + str(x) + "]"
    def show(self, x):
        return self.__fmt(x)
r = Report()
print(r.show(7))
print(r.__fmt(7))

class Point:
    def __init__(self, x):
        self.x = x
    def __eq__(self, other):
        return self.x == other.x
pts = [Point(1), Point(2)]
print(Point(2) in pts, Point(2) is pts[1])

class Shape:
    def area(self):
        return 0
class Square(Shape):
    def __init__(self, side):
        self.side = side
    def area(self, scale):
        return self.side * self.side * scale
print(Square(3).area())

class Calc:
    def double(self, x):
        return x * 2
    def quad(self, x):
        return double(x) * 2
print(Calc().quad(3))

