class A:
    def f(self): return "A" + self.g()
    def g(self): return "a"
class B(A):
    def g(self): return "b"
class C(B):
    def f(self): return "C" + super().f()
print(C().f())

class X:
    def hi(self):
        return "X"
class Y(X): pass
class Z(X):
    def hi(self):
        return "Z"
class W(Y, Z): pass
print(W().hi(), Y().hi())

class Parent:
    def __init__(self):
        self.__code = 42
class Child(Parent):
    def reveal(self):
        return self.__code
c = Child()
print(c.reveal())

class Account:
    def __init__(self):
        self.__bal = 500
    def get(self):
        return self.__bal
acc = Account()
acc.__bal = 0
print(acc.get(), acc.__bal)

class Counter:
    def __init__(self, n):
        self.n = n
    def __add__(self, other):
        self.n = self.n + other.n
        return self
a, b = Counter(2), Counter(3)
c = a + b
print(a.n, c.n, c is a)

class Money:
    def __init__(self, amt):
        self.amt = amt
    def __mul__(self, k):
        return Money(self.amt * k)
m = Money(50)
x = m * 3
y = 3 * m
print(x.amt, y.amt)
